toolArgs.file_text:
@page "/catalog"
@using sv_3642358f7ca44fbb89a23228f2c26008.Services
@inject IProductService ProductService
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-container">
    <aside class="catalog-sidebar">
        <h3>Filters</h3>

        <div class="filter-section">
            <h4>Categories</h4>
            @if (categories is not null)
            {
                @foreach (var category in categories)
                {
                    <label class="filter-checkbox">
                        <input type="checkbox"
                               checked="@IsSelectedCategory(category)"
                               @onchange="@(e => ToggleCategory(category, (bool)e.Value!))" />
                        @category
                    </label>
                }
            }
        </div>

        <div class="filter-section">
            <h4>Price Range</h4>
            <label>
                Min:
                <input type="number" @bind="minPrice" min="0" step="0.01" />
            </label>
            <label>
                Max:
                <input type="number" @bind="maxPrice" min="0" step="0.01" />
            </label>
        </div>

        <div class="filter-section">
            <label class="filter-checkbox">
                <input type="checkbox" @bind="inStockOnly" />
                In Stock Only
            </label>
        </div>

        <div class="filter-actions">
            <button class="btn-apply" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn-clear" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    <main class="catalog-main">
        @if (isLoading)
        {
            <div class="catalog-loading">
                <p>Loading products...</p>
            </div>
        }
        else if (errorMessage is not null)
        {
            <div class="catalog-error">
                <p>@errorMessage</p>
                <button @onclick="LoadProducts">Retry</button>
            </div>
        }
        else if (searchResult is null || searchResult.Items.Count == 0)
        {
            <div class="catalog-empty">
                <p>No products found matching your criteria.</p>
            </div>
        }
        else
        {
            <div class="catalog-toolbar">
                <div class="toolbar-sort">
                    <label>
                        Sort by:
                        <select @bind="sortBy" @bind:after="LoadProducts">
                            <option value="price_asc">Price: Low to High</option>
                            <option value="price_desc">Price: High to Low</option>
                            <option value="name_asc">Name: A-Z</option>
                            <option value="rating_desc">Rating: Highest</option>
                        </select>
                    </label>
                </div>
                <div class="toolbar-info">
                    Showing @(((searchResult.Page - 1) * searchResult.PageSize) + 1)–@(Math.Min(searchResult.Page * searchResult.PageSize, searchResult.TotalCount)) of @searchResult.TotalCount products
                </div>
            </div>

            <div class="product-grid">
                @foreach (var product in searchResult.Items)
                {
                    <ProductCard Product="product"
                                 OnProductSelected="NavigateToProduct"
                                 OnAddToCart="HandleAddToCart" />
                }
            </div>

            <div class="catalog-pagination">
                <button disabled="@(currentPage <= 1)" @onclick="PreviousPage">Previous</button>

                @for (int i = 1; i <= TotalPages; i++)
                {
                    var pageNum = i;
                    <button class="@(pageNum == currentPage ? "page-btn active" : "page-btn")"
                            @onclick="@(() => GoToPage(pageNum))">
                        @pageNum
                    </button>
                }

                <button disabled="@(currentPage >= TotalPages)" @onclick="NextPage">Next</button>
            </div>
        }
    </main>
</div>

@code {
    private List<string>? categories;
    private List<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 12;
    private PagedResult<Product>? searchResult;
    private bool isLoading;
    private string? errorMessage;

    private int TotalPages => searchResult is null || searchResult.PageSize == 0
        ? 1
        : (int)Math.Ceiling((double)searchResult.TotalCount / searchResult.PageSize);

    protected override async Task OnInitializedAsync()
    {
        await LoadCategories();
        await LoadProducts();
    }

    private async Task LoadCategories()
    {
        try
        {
            categories = await ProductService.GetCategoriesAsync();
        }
        catch
        {
            categories = new();
        }
    }

    private async Task LoadProducts()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );

            searchResult = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load products: {ex.Message}";
            searchResult = null;
        }
        finally
        {
            isLoading = false;
        }
    }

    private bool IsSelectedCategory(string category) => selectedCategories.Contains(category);

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
        {
            if (!selectedCategories.Contains(category))
                selectedCategories.Add(category);
        }
        else
        {
            selectedCategories.Remove(category);
        }
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await LoadProducts();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await LoadProducts();
    }

    private async Task GoToPage(int page)
    {
        currentPage = page;
        await LoadProducts();
    }

    private async Task PreviousPage()
    {
        if (currentPage > 1)
        {
            currentPage--;
            await LoadProducts();
        }
    }

    private async Task NextPage()
    {
        if (currentPage < TotalPages)
        {
            currentPage++;
            await LoadProducts();
        }
    }

    private void NavigateToProduct(Product product)
    {
        Navigation.NavigateTo($"/product/{product.Id}");
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        return Task.CompletedTask;
    }
}

