+        try
+        {
+            var filter = new ProductFilter(
+                Categories: selectedCategories.Count > 0 ? selectedCategories : null,
+                MinPrice: minPrice,
+                MaxPrice: maxPrice,
+                InStockOnly: inStockOnly
+            );
+
+            searchResult = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load products: {ex.Message}";
+            searchResult = null;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private bool IsSelectedCategory(string category) => selectedCategories.Contains(category);
+
+    private void ToggleCategory(string category, bool isChecked)
+    {
+        if (isChecked)
+        {
+            if (!selectedCategories.Contains(category))
+                selectedCategories.Add(category);
+        }
+        else
+        {
+            selectedCategories.Remove(category);
+        }
+    }
+
+    private async Task ApplyFilters()
+    {
+        currentPage = 1;
+        await LoadProducts();
+    }
+
+    private async Task ClearFilters()
+    {
+        selectedCategories.Clear();
+        minPrice = null;
+        maxPrice = null;
+        inStockOnly = false;
+        currentPage = 1;
+        await LoadProducts();
+    }
+
+    private async Task GoToPage(int page)
+    {
+        currentPage = page;
+        await LoadProducts();
+    }
+
+    private async Task PreviousPage()
+    {
+        if (currentPage > 1)
+        {
+            currentPage--;
+            await LoadProducts();
+        }
+    }
+
+    private async Task NextPage()
+    {
+        if (currentPage < TotalPages)
+        {
+            currentPage++;
+            await LoadProducts();
+        }
+    }
+
+    private void NavigateToProduct(Product product)
+    {
+        Navigation.NavigateTo($"/product/{product.Id}");
+    }
+
+    private Task HandleAddToCart(Product product)
+    {
+        // Placeholder for add-to-cart logic
+        return Task.CompletedTask;
+    }
+}
